ALTER TYPE "ListingStatus" ADD VALUE 'PENDING';
ALTER TYPE "ListingStatus" ADD VALUE 'REJECTED';
ALTER TABLE "Listing" ALTER COLUMN condition DROP NOT NULL;
ALTER TABLE "Listing" ADD COLUMN "exchangeWish" TEXT NOT NULL DEFAULT '',
  ADD COLUMN "sellerType" TEXT NOT NULL DEFAULT 'PERSONAL',
  ADD COLUMN "attributes" JSONB NOT NULL DEFAULT '{}',
  ADD COLUMN "location" JSONB,
  ADD COLUMN "reviewReason" TEXT;
ALTER TABLE "Category" ADD COLUMN "metadata" JSONB NOT NULL DEFAULT '{}';
ALTER TABLE "Listing" ADD CONSTRAINT "Listing_seller_type_check" CHECK ("sellerType" IN ('PERSONAL','BUSINESS'));
-- Exact coordinates and street addresses must only leave through owner-checked API routes.
ALTER TABLE "Listing" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE "Listing" FROM PUBLIC;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON TABLE "Listing" FROM anon; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON TABLE "Listing" FROM authenticated; END IF;
END $$;

