attery health"},"required":false,"unit":"%","min":1,"max":100},{"key":"warranty","type":"select","label":{"vi":"Bảo hành","en":"Warranty"},"required":false,"options":[{"value":"none","label":{"vi":"Hết bảo hành","en":"No warranty"}},{"value":"manufacturer","label":{"vi":"Còn bảo hành hãng","en":"Manufacturer warranty"}},{"value":"store","label":{"vi":"Bảo hành cửa hàng","en":"Store warranty"}}]}]}'::jsonb)
