CREATE TABLE "ListingFavorite" (
 "userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,
 "listingId" TEXT NOT NULL REFERENCES "Listing"(id) ON DELETE CASCADE,
 "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT "ListingFavorite_pkey" PRIMARY KEY ("userId","listingId")
);
CREATE INDEX "ListingFavorite_listingId_idx" ON "ListingFavorite"("listingId");
ALTER TABLE "ListingFavorite" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE "ListingFavorite" FROM PUBLIC;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON TABLE "ListingFavorite" FROM anon; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON TABLE "ListingFavorite" FROM authenticated; END IF;
END $$;
